import e from"mssql";import{g as n}from"./db.mjs";async function getUserReminder(){try{const e=await n(),t="\n      SELECT \n        id,\n        content,\n        created_at,\n        updated_at\n      FROM user_reminders\n      WHERE id = 1\n    ";return(await e.request().query(t)).recordset[0]||{id:null,content:"",created_at:null,updated_at:null}}catch(e){throw console.error("❌ Get User Reminder Error:",e),e}}async function updateUserReminder(t){try{const r=await n(),a="\n      MERGE user_reminders AS target\n      USING (SELECT 1 AS id) AS source\n      ON (target.id = source.id)\n      WHEN MATCHED THEN\n        UPDATE SET content = @content, updated_at = GETDATE()\n      WHEN NOT MATCHED THEN\n        INSERT (content) VALUES (@content);\n\n      SELECT \n        id,\n        content,\n        created_at,\n        updated_at\n      FROM user_reminders\n      WHERE id = 1;\n    ";return(await r.request().input("content",e.NVarChar(e.MAX),t).query(a)).recordset[0]}catch(e){throw console.error("❌ Update User Reminder Error:",e),e}}export{getUserReminder as g,updateUserReminder as u};
